import itertools

def is_colorful(m, n, w):
    # We need to check if there exists a sequence of length m with values in 1..n
    # such that every window of size w contains all values 1..n.
    # Since m is small, we can try backtracking or just itertools.product for very small m.

    # Optimization: only need to try sequences that are not just permutations.
    # But for m up to 10, product is fine.
    for seq in itertools.product(range(n), repeat=m):
        possible = True
        for i in range(m):
            window = set()
            for j in range(w):
                window.add(seq[(i + j) % m])
            if len(window) < n:
                possible = False
                break
        if possible:
            return True
    return False

