import itertools

def is_colorful(m, n, w):
    # We need to check if there exists a sequence of length m with values in 0..n-1
    # such that every window of size w contains all values 0..n-1.
    # Since m is small, we can use backtracking to be more efficient than itertools.product.

    seq = [-1] * m

    def check(idx):
        # Check if the window ending at idx-1 is valid.
        # The window is [idx-w, ..., idx-1]
        if idx < w:
            return True

        # We only need to check the window that just got completed.
        window = set()
        for j in range(idx - w, idx):
            window.add(seq[j % m])
        if len(window) < n:
            return False
        return True

    def solve(idx):
        if idx == m:
            # Final check: all windows must be valid.
            # The loop in check only checked windows up to m.
            # We need to check windows that wrap around.
            for i in range(m):
                window = set()
                for j in range(w):
                    window.add(seq[(i + j) % m])
                if len(window) < n:
                    return False
            return True

        for c in range(n):
            seq[idx] = c
            # Pruning: if the window ending at idx is already invalid, skip.
            # Wait, the window ending at idx is only fully formed when idx >= w-1.
            if idx >= w - 1:
                # Check window [idx-w+1, ..., idx]
                window = set()
                for j in range(idx - w + 1, idx + 1):
                    window.add(seq[j])
                if len(window) < n:
                    continue

            if solve(idx + 1):
                return True
        return False

    return solve(0)

